package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.voice.*; import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest; import net.fabricmc.fabric.api.client.gametest.v1.context.*; import net.minecraft.server.level.ServerPlayer; @SuppressWarnings("UnstableApiUsage") public final class VoiceClientGameTest implements FabricClientGameTest{public void runTest(ClientGameTestContext context){try(TestSingleplayerContext sp=context.worldBuilder().create()){sp.getServer().runOnServer(server->{var p=server.getPlayerList().getPlayers().stream().findFirst().orElseThrow();VoiceNetworking.send(p,new VoicePacket("hello",1,2,3,16,1,1,1,.5f,3));});context.waitFor(c->TheWorldRemembersClient.lastVoice()!=null,100);if(!"hello".equals(TheWorldRemembersClient.lastVoice().text()))throw new AssertionError("voice payload text mismatch");}}}